<?php
require_once 'config.php'; require_login(); require_admin();
$errors=[]; $editEvent=null;
if ($_SERVER['REQUEST_METHOD']==='POST') {
    verify_csrf(); $action=(string)($_POST['action']??'');
    if ($action==='delete') { $id=filter_input(INPUT_POST,'event_id',FILTER_VALIDATE_INT); if ($id) { $stmt=$pdo->prepare('DELETE FROM events WHERE event_id=?'); $stmt->execute([$id]); set_flash('Event deleted.'); } redirect('admin.php'); }
    if ($action==='save') {
        $id=filter_input(INPUT_POST,'event_id',FILTER_VALIDATE_INT) ?: null; $title=trim((string)($_POST['title']??'')); $description=trim((string)($_POST['description']??'')); $eventDate=trim((string)($_POST['event_date']??'')); $venue=trim((string)($_POST['venue']??'')); $capacity=filter_input(INPUT_POST,'capacity',FILTER_VALIDATE_INT);
        if ($title==='' || mb_strlen($title)>150) $errors[]='Enter an event title (up to 150 characters).';
        if ($description==='') $errors[]='Enter an event description.';
        if ($venue==='' || mb_strlen($venue)>150) $errors[]='Enter a venue (up to 150 characters).';
        $dateObj=DateTime::createFromFormat('Y-m-d\TH:i',$eventDate);
        if (!$dateObj || $dateObj->format('Y-m-d\TH:i')!==$eventDate) $errors[]='Choose a valid event date and time.';
        if (!$capacity || $capacity<1 || $capacity>100000) $errors[]='Capacity must be between 1 and 100000.';
        if (!$errors) { $sqlDate=$dateObj->format('Y-m-d H:i:s'); if ($id) { $stmt=$pdo->prepare('UPDATE events SET title=?,description=?,event_date=?,venue=?,capacity=? WHERE event_id=?'); $stmt->execute([$title,$description,$sqlDate,$venue,$capacity,$id]); set_flash('Event updated successfully.'); } else { $stmt=$pdo->prepare('INSERT INTO events (title,description,event_date,venue,capacity,created_by,created_at) VALUES (?,?,?,?,?,?,NOW())'); $stmt->execute([$title,$description,$sqlDate,$venue,$capacity,$_SESSION['user_id']]); set_flash('New event added successfully.'); } redirect('admin.php'); }
        $editEvent=['event_id'=>$id,'title'=>$title,'description'=>$description,'event_date'=>$eventDate,'venue'=>$venue,'capacity'=>$capacity];
    }
}
if (isset($_GET['edit']) && !$editEvent) { $id=filter_input(INPUT_GET,'edit',FILTER_VALIDATE_INT); if ($id) { $stmt=$pdo->prepare('SELECT * FROM events WHERE event_id=?'); $stmt->execute([$id]); $editEvent=$stmt->fetch() ?: null; if ($editEvent) $editEvent['event_date']=date('Y-m-d\TH:i',strtotime($editEvent['event_date'])); } }
$events=$pdo->query('SELECT e.*, (SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.event_id) AS registered_count FROM events e ORDER BY e.event_date DESC')->fetchAll();
$pageTitle='Admin Dashboard'; require 'header.php';
?>
<section class="page-intro"><span class="eyebrow">EVENT MANAGEMENT</span><h1>Admin Dashboard</h1><p>Add events, update event information, and review registered participants.</p></section>
<div class="admin-layout"><section class="admin-form-panel"><h2><?= $editEvent ? 'Edit event' : 'Add a new event' ?></h2><?php foreach ($errors as $error): ?><div class="alert error"><?= e($error) ?></div><?php endforeach; ?><form method="post" class="form-stack"><input type="hidden" name="csrf_token" value="<?= e($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="event_id" value="<?= e($editEvent['event_id']??'') ?>"><label for="title">Event title</label><input id="title" name="title" maxlength="150" required value="<?= e($editEvent['title']??'') ?>"><label for="description">Description</label><textarea id="description" name="description" rows="5" required><?= e($editEvent['description']??'') ?></textarea><label for="event_date">Date and time</label><input id="event_date" type="datetime-local" name="event_date" required value="<?= e($editEvent['event_date']??'') ?>"><label for="venue">Venue</label><input id="venue" name="venue" maxlength="150" required value="<?= e($editEvent['venue']??'') ?>"><label for="capacity">Capacity</label><input id="capacity" type="number" name="capacity" min="1" max="100000" required value="<?= e($editEvent['capacity']??'50') ?>"><button class="btn btn-primary" type="submit"><?= $editEvent ? 'Save changes' : 'Add event' ?></button><?php if ($editEvent): ?><a class="btn btn-outline" href="admin.php">Cancel editing</a><?php endif; ?></form></section>
<section class="admin-list-panel"><h2>Manage events</h2><?php if (!$events): ?><p class="muted">No events have been added yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Event</th><th>Date</th><th>Registrations</th><th>Actions</th></tr></thead><tbody><?php foreach ($events as $event): ?><tr><td><strong><?= e($event['title']) ?></strong><small><?= e($event['venue']) ?></small></td><td><?= e(date('M d, Y',strtotime($event['event_date']))) ?></td><td><?= (int)$event['registered_count'] ?> / <?= (int)$event['capacity'] ?><br><a class="table-link" href="admin.php?attendees=<?= (int)$event['event_id'] ?>">View participants</a></td><td><div class="table-actions"><a class="table-link" href="admin.php?edit=<?= (int)$event['event_id'] ?>">Edit</a><form method="post" onsubmit="return confirm('Delete this event and its registrations?');"><input type="hidden" name="csrf_token" value="<?= e($_SESSION['csrf_token']) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="event_id" value="<?= (int)$event['event_id'] ?>"><button class="link-danger" type="submit">Delete</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></div>
<?php if (isset($_GET['attendees'])): $attendeeEventId=filter_input(INPUT_GET,'attendees',FILTER_VALIDATE_INT); $attendeeEvent=null; $attendees=[]; if ($attendeeEventId) { $q=$pdo->prepare('SELECT title FROM events WHERE event_id=?'); $q->execute([$attendeeEventId]); $attendeeEvent=$q->fetch(); if ($attendeeEvent) { $q=$pdo->prepare('SELECT u.name,u.email,r.registered_at FROM registrations r JOIN users u ON r.user_id=u.user_id WHERE r.event_id=? ORDER BY r.registered_at'); $q->execute([$attendeeEventId]); $attendees=$q->fetchAll(); } } ?><section class="attendees-panel"><h2>Participants: <?= e($attendeeEvent['title']??'Event not found') ?></h2><?php if (!$attendeeEvent): ?><p>Event not found.</p><?php elseif (!$attendees): ?><p>No students have registered for this event yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Registered at</th></tr></thead><tbody><?php foreach ($attendees as $person): ?><tr><td><?= e($person['name']) ?></td><td><?= e($person['email']) ?></td><td><?= e(date('M d, Y g:i A',strtotime($person['registered_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section><?php endif; ?>
<?php require 'footer.php'; ?>
